{{velocity}} ## Personal space home page — auto-initializes on first access. ## This page serves as the template/content for ~username.WebHome pages. ## ## Get the username from the current space name (remove the leading tilde) #set ($spaceRefs = $doc.documentReference.spaceReferences) #if ($spaceRefs.size() > 0) #set ($topSpace = $spaceRefs.get(0).name) #else #set ($topSpace = '') #end ## ## Auto-initialize: if this is a ~username space and no SpaceClass object exists, create one. #if ($topSpace.startsWith('~') && !$doc.getObject('SpaceCode.SpaceClass')) #set ($userName = $topSpace.substring(1)) #set ($spaceObj = $doc.newObject('SpaceCode.SpaceClass')) $!spaceObj.set('name', "Personal Space of ${userName}") $!spaceObj.set('key', $topSpace) $!spaceObj.set('description', "Personal space for user ${userName}") $!spaceObj.set('type', 'personal') $!spaceObj.set('owner', "xwiki:XWiki.${userName}") #set ($discard = $doc.save('Auto-initialized personal space')) #end ## ## Display personal space home content #set ($userName = $topSpace.substring(1)) #set ($userDoc = $xwiki.getDocument("XWiki.${userName}")) #set ($displayName = "$!userDoc.display('name')") #if ($displayName == '') #set ($displayName = $userName) #end = $services.localization.render('spaces.personal.title'): $escapetool.xml($displayName) =
{{info}} $services.localization.render('spaces.personal.welcome', [$escapetool.xml($displayName)]) {{/info}}
== $services.localization.render('spaces.personal.pages') ==
{{documentTree showTranslations="false" showAttachments="false" compact="true" root="space:${escapetool.xml($topSpace)}" /}}
== $services.localization.render('spaces.personal.recentChanges') ==
{{recentlyModified count="10" spaces="${escapetool.xml($topSpace)}" /}} {{/velocity}}
